func parseMatcherDefinitions(d *caddyfile.Dispenser, matchers map[string]caddy.ModuleMap) error {
	d.Next() // advance to the first token

	definitionName := d.Val()
	if _, ok := matchers[definitionName]; ok {
		return fmt.Errorf("matcher is defined more than once: %s", definitionName)
	}
	matchers[definitionName] = make(caddy.ModuleMap)
	matcherLabel := definitionName[1:]

	if d.NextArg() {
		currentToken := d.Token()
		if currentToken.Quoted() {
			expressionToken := caddyfile.Token{
				Text: "expression",
				File: d.File(),
				Line: d.Line(),
			}
			exprDispenser := caddyfile.NewDispenser([]caddyfile.Token{expressionToken, currentToken})
			exprDispenser.SetContext(caddyfile.MatcherNameCtxKey, matcherLabel)
			exprDispenser.Next()
			remainingArgs := 0
			for exprDispenser.NextArg() {
				remainingArgs++
			}
			for rewind := 0; rewind < remainingArgs; rewind++ {
				exprDispenser.Prev()
			}
			exprMatcher := new(caddyhttp.MatchExpression)
			if remainingArgs == 0 {
				return exprDispenser.ArgErr()
			}
			exprDispenser.NextArg()
			exprMatcher.Expr = exprDispenser.Val()
			contextName := exprDispenser.GetContextString(caddyfile.MatcherNameCtxKey)
			if contextName != "" {
				exprMatcher.Name = contextName
				encoded, err := json.Marshal(exprMatcher)
				if err != nil {
					matchers[definitionName]["expression"] = nil
				} else {
					matchers[definitionName]["expression"] = encoded
				}
			} else {
				encoded, err := json.Marshal(exprMatcher)
				if err != nil {
					matchers[definitionName]["expression"] = nil
				} else {
					matchers[definitionName]["expression"] = encoded
				}
			}
			return nil
		}
		d.Prev()
	}

	tokensByMatcherName := make(map[string][]caddyfile.Token)
	for nesting := d.Nesting(); d.NextArg() || d.NextBlock(nesting); {
		matcherName := d.Val()
		segmentTokens := []caddyfile.Token{d.Token()}
		for d.NextArg() {
			segmentTokens = append(segmentTokens, d.Token())
		}
		openedBlock := false
		for blockNesting := d.Nesting(); d.NextBlock(blockNesting); {
			if !openedBlock {
				d.Prev()
				segmentTokens = append(segmentTokens, d.Token())
				d.Next()
				openedBlock = true
			}
			segmentTokens = append(segmentTokens, d.Token())
		}
		if openedBlock {
			segmentTokens = append(segmentTokens, d.Token())
		}
		tokensByMatcherName[matcherName] = append(tokensByMatcherName[matcherName], segmentTokens...)
	}

	for matcherName, tokens := range tokensByMatcherName {
		dispenser := caddyfile.NewDispenser(tokens)
		dispenser.SetContext(caddyfile.MatcherNameCtxKey, matcherLabel)
		var encodedValue any
		if matcherName == "not" {
			notMatcher := caddyhttp.MatchNot{}
			for dispenser.Next() {
				nestedMatcherMap := make(map[string]caddyhttp.RequestMatcher)
				nestedTokensByName := make(map[string][]caddyfile.Token)
				for nestedNesting := dispenser.Nesting(); dispenser.NextArg() || dispenser.NextBlock(nestedNesting); {
					nestedMatcherName := dispenser.Val()
					nestedTokensByName[nestedMatcherName] = append(nestedTokensByName[nestedMatcherName], dispenser.NextSegment()...)
				}
				for nestedMatcherName, nestedTokens := range nestedTokensByName {
					mod, err := caddy.GetModule("http.matchers." + nestedMatcherName)
					if err != nil {
						return dispenser.Errf("getting matcher module '%s': %v", nestedMatcherName, err)
					}
					unm, ok := mod.New().(caddyfile.Unmarshaler)
					if !ok {
						return dispenser.Errf("matcher module '%s' is not a Caddyfile unmarshaler", nestedMatcherName)
					}
					err = unm.UnmarshalCaddyfile(caddyfile.NewDispenser(nestedTokens))
					if err != nil {
						return err
					}
					rm, ok := unm.(caddyhttp.RequestMatcher)
					if !ok {
						return fmt.Errorf("matcher module '%s' is not a request matcher", nestedMatcherName)
					}
					nestedMatcherMap[nestedMatcherName] = rm
				}
				matcherSet := make(caddy.ModuleMap)
				for nestedName, nestedMatcher := range nestedMatcherMap {
					jsonBytes, err := json.Marshal(nestedMatcher)
					if err != nil {
						return fmt.Errorf("marshaling %T matcher: %v", nestedMatcher, err)
					}
					matcherSet[nestedName] = jsonBytes
				}
				notMatcher.MatcherSetsRaw = append(notMatcher.MatcherSetsRaw, matcherSet)
			}
			encodedValue = notMatcher
		} else {
			mod, err := caddy.GetModule("http.matchers." + matcherName)
			if err != nil {
				return fmt.Errorf("getting matcher module '%s': %v", matcherName, err)
			}
			unm, ok := mod.New().(caddyfile.Unmarshaler)
			if !ok {
				return fmt.Errorf("matcher module '%s' is not a Caddyfile unmarshaler", matcherName)
			}
			err = unm.UnmarshalCaddyfile(dispenser)
			if err != nil {
				return err
			}
			rm, ok := unm.(caddyhttp.RequestMatcher)
			if !ok {
				return fmt.Errorf("matcher module '%s' is not a request matcher", matcherName)
			}
			encodedValue = rm
		}
		encoded, err := json.Marshal(encodedValue)
		if err != nil {
			matchers[definitionName][matcherName] = nil
		} else {
			matchers[definitionName][matcherName] = encoded
		}
	}
	return nil
}

func encodeMatcherSet(matchers map[string]caddyhttp.RequestMatcher) (caddy.ModuleMap, error) {
	msEncoded := make(caddy.ModuleMap)
	for matcherName, val := range matchers {
		jsonBytes, err := json.Marshal(val)
		if err != nil {
			return nil, fmt.Errorf("marshaling matcher set %#v: %v", matchers, err)
		}
		msEncoded[matcherName] = jsonBytes
	}
	return msEncoded, nil
}

// WasReplacedPlaceholderShorthand checks if a token string was
// likely a replaced shorthand of the known Caddyfile placeholder
// replacement outputs. Useful to prevent some user-defined map
// output destinations from overlapping with one of the
// predefined shorthands.
func WasReplacedPlaceholderShorthand(token string) string {
	prev := ""
	for i, item := range placeholderShorthands() {
		// only look at every 2nd item, which is the replacement
		if i%2 == 0 {
			prev = item
			continue
		}
		if strings.Trim(token, "{}") == strings.Trim(item, "{}") {
			// we return the original shorthand so it
			// can be used for an error message
			return prev
		}
	}
	return ""
}

// tryInt tries to convert val to an integer. If it fails,
// it downgrades the error to a warning and returns 0.
func tryInt(val any, warnings *[]caddyconfig.Warning) int {
	intVal, ok := val.(int)
	if val != nil && !ok && warnings != nil {
		*warnings = append(*warnings, caddyconfig.Warning{Message: "not an integer type"})
	}
	return intVal
}

func tryString(val any, warnings *[]caddyconfig.Warning) string {
	stringVal, ok := val.(string)
	if val != nil && !ok && warnings != nil {
